/**
 * @name: camel-case ;
 * @author: linzp ;
 * @description: 将字符串转化成驼峰 ;
 * */

const camelCase = (name, options) => {
    const {caseStyle} = Object.assign({}, options);
    return (name.charAt(0)[caseStyle === 'lower' ? 'toLowerCase' : 'toUpperCase']() + name.slice(1).replace(/[-_](\w)/g, (m, n) => n.toUpperCase()));
};

export default camelCase;

